#define MAXN 12
#define INF 1e100
#define EPS 1e-10

/*
   We place all circles on the bottom line y = r_i.
   If circles i and j (radii ri, rj) both touch the bottom and each other,
   then horizontal distance between centers is:
      dx = 2 * sqrt(ri * rj)

   For a fixed left-to-right order, the minimum x-position of each circle
   can be greedily determined:
      x[i] = max over j<i of (x[j] + 2*sqrt(r[i]*r[j]))
   and also x[i] >= r[i] if using actual coordinates.
   Since width only depends on relative positions, we use left edge = x-r.
   Equivalent total width for an order can be computed from center positions.

   We must determine whether there exists some permutation whose total width <= W.

   n <= 12, so use DP over subsets.
   State:
     dp[mask][last] = minimal possible rightmost extent (max_k x_k + r_k)
                      among arrangements of circles in 'mask' whose last
                      (rightmost in order) circle is 'last', with the circles
                      packed greedily in that order.

   To append circle i after subset mask ending with last is not enough,
   because x[i] depends on all previous circles, not only the last one.
   So instead we store the whole profile indirectly by using exact recurrence
   over subset:
     pos[mask][i] = x-position of i in the greedy placement for the optimal
                    arrangement? Not enough.

   Since n<=12, we can do DFS over permutations with strong pruning.
   For each partial order, maintain x positions of placed circles and current
   used width. This is sufficient and simple.

   Additional pruning:
   - sort radii to remove duplicate permutations
   - current width already > W => prune
   - lower bound: current width plus sum of diameters of unplaced circles is
     not valid, so omitted.
*/

static int n;
static int W;
static int r[MAXN];
static double dista[MAXN][MAXN];
static int used[MAXN];
static double xpos[MAXN];
static int order_idx[MAXN];
static int found;

static void dfs(int depth, double currentRight) {
    if (found) return;
    if (currentRight - EPS > (double)W) return;

    if (depth == n) {
        found = 1;
        return;
    }

    int prevRadius = -1;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (r[i] == prevRadius) continue; /* avoid duplicate permutations */
        prevRadius = r[i];

        double x = (double)r[i];
        for (int k = 0; k < depth; k++) {
            int j = order_idx[k];
            double cand = xpos[j] + dista[i][j];
            if (cand > x) x = cand;
        }

        double newRight = currentRight;
        if (x + r[i] > newRight) newRight = x + r[i];
        if (newRight - EPS > (double)W) continue;

        used[i] = 1;
        xpos[i] = x;
        order_idx[depth] = i;
        dfs(depth + 1, newRight);
        used[i] = 0;

        if (found) return;
    }
}

static int cmp_int(const void *a, const void *b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return x - y;
}

