static const double EPS = 1e-10;

// Minimal width needed for a fixed order of circles placed on the floor.
// Circles have centers at (x_i, r_i), tangent to the bottom y=0,
// and must not overlap.
double width_for_order(const vector<int>& r) {
    int n = (int)r.size();
    vector<double> x(n, 0.0);

    for (int i = 0; i < n; ++i) {
        double xi = r[i]; // at least touches the left wall if first/possible
        for (int j = 0; j < i; ++j) {
            double dx = 2.0 * sqrt((double)r[i] * r[j]);
            xi = max(xi, x[j] + dx);
        }
        x[i] = xi;
    }

    double right = 0.0;
    for (int i = 0; i < n; ++i) {
        right = max(right, x[i] + r[i]);
    }
    return right;
}

