public class Main {
    static double[] radii;
    static int n;
    static double boxWidth;
    static boolean found;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            boxWidth = sc.nextInt();
            List<Integer> list = new ArrayList<>();
            while (sc.hasNextInt()) {
                int r = sc.nextInt();
                if (r == 0) break; // not in problem but safe guard
                list.add(r);
            }
            n = list.size();
            radii = new double[n];
            for (int i = 0; i < n; i++) {
                radii[i] = list.get(i);
            }
            found = false;
            boolean[] used = new boolean[n];
            backtrack(new ArrayList<>(), used);
            System.out.println(found ? "OK" : "NA");
        }
        sc.close();
    }

    static void backtrack(List<Double> placed, boolean[] used) {
        if (found) return;
        if (placed.size() == n) {
            double width = placed.get(placed.size() - 1) + radii[perm[placed.size() - 1]];
            if (width <= boxWidth + 1e-9) {
                found = true;
            }
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                double x = placeNext(placed, i);
                if (x + radii[i] <= boxWidth + 1e-9) {
                    placed.add(x);
                    backtrack(placed, used);
                    placed.remove(placed.size() - 1);
                }
                used[i] = false;
                if (found) return;
            }
        }
    }

    // store permutation to know which radius index
    static List<Integer> perm = new ArrayList<>();

    static double placeNext(List<Double> placed, int idx) {
        perm.add(idx);
        if (placed.isEmpty()) {
            return radii[idx]; // against left wall
        }
        double maxX = radii[idx];
        for (int j = 0; j < placed.size(); j++) {
            double rj = radii[perm.get(j)];
            double ri = radii[idx];
            double dist = 2 * Math.sqrt(rj * ri);
            double candidate = placed.get(j) + dist;
            maxX = Math.max(maxX, candidate);
        }
        return maxX;
    }
}

