public class Main {
    static final double EPS = 1e-9;

    static double dist(int a, int b) {
        return 2.0 * Math.sqrt((double) a * b);
    }

    static boolean canFit(int W, int[] r) {
        int n = r.length;
        int N = 1 << n;

        double[][] dp = new double[N][n];
        for (int i = 0; i < N; i++) Arrays.fill(dp[i], Double.POSITIVE_INFINITY);

        for (int i = 0; i < n; i++) {
            dp[1 << i][i] = 2.0 * r[i];
        }

        for (int mask = 1; mask < N; mask++) {
            for (int last = 0; last < n; last++) {
                double cur = dp[mask][last];
                if (cur == Double.POSITIVE_INFINITY) continue;

                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    int nmask = mask | (1 << nxt);
                    double cand = cur + dist(r[last], r[nxt]);
                    if (cand < dp[nmask][nxt]) dp[nmask][nxt] = cand;
                }
            }
        }

        int full = N - 1;
        double best = Double.POSITIVE_INFINITY;
        for (int last = 0; last < n; last++) {
            best = Math.min(best, dp[full][last]);
        }

        return best <= W + EPS;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) continue;

            int W = Integer.parseInt(st.nextToken());
            ArrayList<Integer> list = new ArrayList<>();
            while (st.hasMoreTokens()) {
                list.add(Integer.parseInt(st.nextToken()));
            }

            int[] r = new int[list.size()];
            for (int i = 0; i < r.length; i++) r[i] = list.get(i);

            if (r.length == 0) {
                out.append("OK\n");
            } else {
                out.append(canFit(W, r) ? "OK" : "NA").append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

