import sys
import math

def can_fit(W, radii):
    n = len(radii)
    if n == 0:
        return True

    # Sort for stronger pruning
    radii = sorted(radii, reverse=True)

    # Precompute horizontal distances needed between touching circles on the floor:
    # centers are at heights ri and rj, tangent distance gives
    # dx = 2 * sqrt(ri * rj)
    dist = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            dist[i][j] = 2.0 * math.sqrt(radii[i] * radii[j])

    fullmask = (1 << n) - 1
    INF = 1e100

    # dp[mask][last] = minimum possible rightmost x-coordinate of the center
    # of 'last' after placing exactly the set 'mask' in some order ending with 'last',
    # while keeping all circles tangent to/above floor and non-overlapping.
    dp = [[INF] * n for _ in range(1 << n)]

    for i in range(n):
        dp[1 << i][i] = radii[i]  # left wall to center

    for mask in range(1 << n):
        for last in range(n):
            cur = dp[mask][last]
            if cur >= INF:
                continue
            # current total used width is cur + radius(last)
            if cur + radii[last] > W + 1e-12:
                continue
            rem = fullmask ^ mask
            while rem:
                b = rem & -rem
                nxt = b.bit_length() - 1
                rem -= b
                newx = cur + dist[last][nxt]
                if newx < dp[mask | (1 << nxt)][nxt]:
                    dp[mask | (1 << nxt)][nxt] = newx

    for last in range(n):
        if dp[fullmask][last] + radii[last] <= W + 1e-12:
            return True
    return False

def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        vals = list(map(int, line.split()))
        W = vals[0]
        radii = vals[1:]
        out.append("OK" if can_fit(W, radii) else "NA")
    print("\n".join(out))

